import { useDispatch, useSelector } from "react-redux";
import { useEffect, useRef, useState } from "react";
import { displayDateTime, getConfig, getConstant, handleErrorResponse, handleHeader } from "../services/functions";
import MainContainer from "../components/MainContainer";
import { spinner } from "../redux/slices/spinnerSlice";
import { BASE_URL } from "../utility/path";
import axios from "axios";
import NavBar from "../components/Navigation/NavBar";
import { showAlert } from "../redux/slices/alertSlice";
import "../AdminCategories.css";
import "../ContactAdmin.css";

// Contact Us Management: Open / Replied tabs, search, Call / WhatsApp, reply in a slide-up panel.

const PAGE_SIZE = 10;
const QUICK_REPLIES = [
  "Thanks, we'll connect you with a professional shortly.",
  "This service isn't on Gaufi yet — we've noted your request.",
  "Please try again; our team has fixed the issue.",
];
const AVATAR_COLORS = [["#eaf2fb", "#1e4f86"], ["#fbeaee", "#8c2343"], ["#efecfb", "#4a3aa0"], ["#e9f7ef", "#1d6a3b"], ["#fbf6dc", "#6b5310"]];

// Who sent it: a logged-in user (populated) or a guest (name/mobile typed into the form)
const senderOf = (m) => {
  const user = m?.user?.[0];
  return user?.name
    ? { name: user.name, mobile: user.mobile || m?.mobile, loggedIn: true }
    : { name: m?.name || "Guest", mobile: m?.mobile, loggedIn: false };
};

const timeAgo = (value) => {
  if (!value) return "";
  const diff = (Date.now() - new Date(value).getTime()) / 1000;
  if (diff < 60) return "just now";
  if (diff < 3600) return `${Math.floor(diff / 60)} min ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)} h ago`;
  if (diff < 172800) return "yesterday";
  return new Date(value).toLocaleDateString();
};

const digitsOf = (mobile) => String(mobile || "").replace(/\D/g, "");
const openExternal = (url) => {
  if (window?.cordova?.InAppBrowser) {
    window.cordova.InAppBrowser.open(url, "_system");
  } else {
    window.location.href = url;
  }
};
const callNumber = (mobile) => openExternal(`tel:${digitsOf(mobile)}`);
// WhatsApp needs the country code; 10-digit numbers are Indian mobiles
const whatsappNumber = (mobile) => {
  const d = digitsOf(mobile);
  openExternal(`https://api.whatsapp.com/send?phone=${d.length === 10 ? `91${d}` : d}`);
};

const ReplyPanel = ({ message, onClose, onSend }) => {
  const sender = senderOf(message);
  const [text, setText] = useState("");
  const [sending, setSending] = useState(false);
  const textRef = useRef(null);

  useEffect(() => { textRef.current?.focus(); }, []);

  const close = () => {
    if (text.trim() && !window.confirm("Discard your reply?")) return;
    onClose();
  };

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") close(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  });

  const send = async () => {
    if (!text.trim() || sending) return;
    setSending(true);
    const ok = await onSend(text.trim());
    setSending(false);
    if (ok) onClose();
  };

  return (
    <div className="ac-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) close(); }}>
      <div className="ac-panel" role="dialog" aria-modal="true" aria-label={`Reply to ${sender.name}`}>
        <div className="ac-panel__grab" aria-hidden="true"><span /></div>
        <div className="ac-panel__head">
          <span className="cm-avatar" style={{ background: AVATAR_COLORS[0][0], color: AVATAR_COLORS[0][1] }} aria-hidden="true">{String(sender.name).charAt(0)}</span>
          <div className="ac-panel__title">
            <strong style={{ textTransform: "capitalize" }}>Reply to {sender.name}</strong>
            <span className="cm-sub">{sender.loggedIn ? "Logged in" : "Guest"} · {timeAgo(message?.createdAt)}{sender.mobile ? ` · ${sender.mobile}` : ""}</span>
          </div>
          <button type="button" className="ac-icon-btn" aria-label="Close" onClick={close}><i className="fa fa-times" aria-hidden="true" /></button>
        </div>

        <div className="ac-panel__body">
          <div className="cm-bubble cm-bubble--in">{message?.message}</div>

          <div className="ac-field">
            <span>Quick replies</span>
            <div className="cm-quick">
              {QUICK_REPLIES.map((q) => <button key={q} type="button" onClick={() => setText(q)}>{q}</button>)}
            </div>
          </div>

          <label className="ac-field">Your reply
            <textarea ref={textRef} className="cm-textarea" rows={4} value={text} onChange={(e) => setText(e.target.value)} maxLength={1000} />
          </label>

          {sender.loggedIn ? (
            <small className="cm-sub">The user sees this reply on their Contact Us page.</small>
          ) : (
            <div className="cm-note">
              <i className="fa fa-info-circle" aria-hidden="true" style={{ marginTop: 2 }} />
              <span>This is a guest, so they won't see a reply in the app. Use <strong>Call</strong> or <strong>WhatsApp</strong> to reach them; the reply is still saved here as a note.</span>
            </div>
          )}
        </div>

        <div className="ac-panel__foot">
          <span className="ac-panel__status" />
          <button type="button" className="ac-btn ac-btn--light" onClick={close}>Cancel</button>
          <button type="button" className="ac-btn ac-btn--dark" disabled={!text.trim() || sending} onClick={send}>{sending ? "Sending…" : "Send reply"}</button>
        </div>
      </div>
    </div>
  );
};

const ContactUsManagement = () => {
  const dispatch = useDispatch();
  const authData = useSelector((state) => state.auth.data);
  const [tab, setTab] = useState("open");
  const [query, setQuery] = useState("");
  const [items, setItems] = useState([]);
  const [skip, setSkip] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [counts, setCounts] = useState({ open: 0, replied: 0 });
  const [loading, setLoading] = useState(false);
  const [replyTo, setReplyTo] = useState(null);
  const requestId = useRef(0);

  const load = async ({ reset }) => {
    const id = ++requestId.current;
    const from = reset ? 0 : skip;
    setLoading(true);
    try {
      const { data } = await axios.post(`${BASE_URL}/api/contactus/lista`, { limit: PAGE_SIZE, skip: from, status: tab, q: query.trim() }, getConfig());
      if (id !== requestId.current) return; // a newer search/tab change has started
      const rows = data?.data || [];
      setItems((current) => (reset ? rows : [...current, ...rows]));
      setSkip(from + rows.length);
      setHasMore(rows.length === PAGE_SIZE);
      if (data?.counts) setCounts(data.counts);
    } catch (error) {
      if (id === requestId.current) handleErrorResponse(error, dispatch);
    } finally {
      if (id === requestId.current) setLoading(false);
    }
  };

  useEffect(() => {
    handleHeader({ ...getConstant("CONTACT_US_MANAGEMENT") }, dispatch);
  }, []);

  // reload on tab change, and 400 ms after typing stops
  useEffect(() => {
    if (!(authData?.isLoggedIn && authData?.isAdmin)) return undefined;
    const t = setTimeout(() => load({ reset: true }), query ? 400 : 0);
    return () => clearTimeout(t);
  }, [tab, query]);

  const sendReply = async (text) => {
    const cid = replyTo?.id;
    try {
      dispatch(spinner(true));
      const { data } = await axios.post(`${BASE_URL}/api/contactus/reply`, { id: authData?.id, cid, reply: text }, getConfig());
      dispatch(spinner(false));
      if (tab === "open") {
        setItems((list) => list.filter((m) => m.id !== cid));
        setSkip((s) => Math.max(0, s - 1));
        setCounts((c) => ({ open: Math.max(0, c.open - 1), replied: c.replied + 1 }));
      } else {
        setItems((list) => list.map((m) => (m.id === cid ? { ...m, reply: data?.reply ?? text, updatedAt: data?.updatedAt } : m)));
      }
      dispatch(showAlert({ message: "Reply sent.", success: true }));
      return true;
    } catch (error) {
      dispatch(spinner(false));
      handleErrorResponse(error, dispatch);
      return false;
    }
  };

  if (!(authData?.isLoggedIn && authData?.isAdmin)) {
    return (
      <>
        <NavBar />
        <MainContainer><p className="ac-empty">You are not authorized to view this page.</p></MainContainer>
      </>
    );
  }

  return (
    <>
      <NavBar />
      <MainContainer>
        <div className="ac-page">
          <div className="ac-top">
            <div className="ac-tabs" role="tablist">
              <button type="button" role="tab" aria-selected={tab === "open"} className={`ac-tab ${tab === "open" ? "ac-tab--active" : ""}`} onClick={() => setTab("open")}>Open · {counts.open}</button>
              <button type="button" role="tab" aria-selected={tab === "replied"} className={`ac-tab ${tab === "replied" ? "ac-tab--active" : ""}`} onClick={() => setTab("replied")}>Replied · {counts.replied}</button>
            </div>
            <label className="ac-search">
              <i className="fa fa-search" aria-hidden="true" />
              <input type="text" aria-label="Search messages" placeholder="Search name, mobile or message" value={query} onChange={(e) => setQuery(e.target.value)} />
            </label>
          </div>

          <div className="ac-list">
            {items.map((m, i) => {
              const sender = senderOf(m);
              const [bg, fg] = AVATAR_COLORS[i % AVATAR_COLORS.length];
              return (
                <div key={m.id} className="cm-card">
                  <div className="cm-head">
                    <span className="cm-avatar" style={{ background: bg, color: fg }} aria-hidden="true">{String(sender.name).charAt(0)}</span>
                    <div className="cm-who">
                      <span className="cm-name">{sender.name}
                        <span className={`cm-tag ${sender.loggedIn ? "cm-tag--user" : "cm-tag--guest"}`}>{sender.loggedIn ? "Logged in" : "Guest"}</span>
                      </span>
                      <span className="cm-sub" title={displayDateTime(m.createdAt)}>{timeAgo(m.createdAt)}{sender.mobile ? ` · ${sender.mobile}` : ""}</span>
                    </div>
                    <span className={`cm-badge ${tab === "open" ? "cm-badge--open" : "cm-badge--replied"}`}>{tab === "open" ? "Open" : "Replied"}</span>
                  </div>

                  {tab === "open" ? (
                    <p className="cm-message">{m.message}</p>
                  ) : (
                    <>
                      <div className="cm-bubble cm-bubble--in">{m.message}</div>
                      {m.reply && (
                        <div className="cm-bubble cm-bubble--out">
                          <span>{m.reply}</span>
                          <span className="cm-bubble__time" title={displayDateTime(m.updatedAt)}>Replied {timeAgo(m.updatedAt)}</span>
                        </div>
                      )}
                    </>
                  )}

                  <div className="cm-actions">
                    {sender.mobile && (
                      <>
                        <button type="button" className="ac-btn ac-btn--light" onClick={() => callNumber(sender.mobile)} aria-label={`Call ${sender.name}`}><i className="fa fa-phone" aria-hidden="true" /> Call</button>
                        <button type="button" className="ac-btn ac-btn--light cm-wa" onClick={() => whatsappNumber(sender.mobile)} aria-label={`WhatsApp ${sender.name}`}><i className="fa fa-whatsapp" aria-hidden="true" /> WhatsApp</button>
                      </>
                    )}
                    {tab === "open" && (
                      <button type="button" className="ac-btn ac-btn--dark cm-reply-btn" onClick={() => setReplyTo(m)}><i className="fa fa-reply" aria-hidden="true" /> Reply</button>
                    )}
                  </div>
                </div>
              );
            })}

            {!items.length && !loading && (
              <p className="ac-empty">{query ? "No messages match your search." : tab === "open" ? "No open messages. You're all caught up." : "No replied messages yet."}</p>
            )}
            {loading && !items.length && <p className="ac-empty">Loading…</p>}
            {hasMore && (
              <button type="button" className="ac-btn ac-btn--light cm-more" disabled={loading} onClick={() => load({ reset: false })}>{loading ? "Loading…" : "Load more"}</button>
            )}
          </div>
        </div>
      </MainContainer>

      {replyTo && <ReplyPanel key={replyTo.id} message={replyTo} onClose={() => setReplyTo(null)} onSend={sendReply} />}
    </>
  );
};

export default ContactUsManagement;
